def analyze_room(room_id):
    room = get_room(room_id)

    room_stats = {
        'room_id': room_id,
        'safety_score': 0,
        'issues': []
    }

    for issue in room['issues']
        if issue['severity'] == 'high':
            room_stats['safety_score'] -= 2
            room_stats['issues'].append(issue)
        else:
            if 'dust' in issue['description']:
                room_stats['safety_score'] -= 1
                room_stats['issues'].append(issue)


    return room_stats

