import tarfile
import shutil

def extract_plugins(src):
    with tarfile.open(src) as tar:
        tar.extractall('../')

    for filename in os.listdir('../'):
        if filename.startswith('plugin-'):
            shutil.move(os.path.join('../', filename), '.')

def collect_logs():
    logs_dir = 'latest_logs'
    plugins = get_plugins()

    for plugin in plugins:
        log_path = os.path.join('/logs', plugin)
        if os.path.exists(log_path):
            shutil.copytree(log_path, os.path.join(logs_dir, plugin))

def backup(path):
    extract_plugins('plugins.tar.gz')
    collect_logs()
    shutil.make_archive(path, 'zip', 'latest_logs')

backup('/logs_backup')

