import os

def move_and_rename_images_dir(dir_path):
    if not os.path.exists(dir_path + "/../archive"):
        os.mkdir(dir_path + "/../archive")

    for filename in os.listdir(dir_path):
        if filename.endswith(".jpg"):
            shutil.move(os.path.join(dir_path, filename),
                        os.path.join(dir_path, "../archive", filename))

    if len(os.listdir(dir_path)) == 0:
        os.rmdir(dir_path)

    os.chmod(dir_path + "/../archive", 0o777)

