import numpy as np
from math import sqrt

data = np.load('data.npy')

def covariance(x, y):
    return np.dot(x - np.mean(x), y - np.mean(y)) / (len(x) - 1)

def standard_dev(x):
    return sqrt(covariance(x, x))

def correlation(x, y):
    return covariance(x, y) / (standard_dev(x) * standard_dev(y))

