def merge(a, b):
    if not a or not b:
        return a + b

    if a[0] < b[0]:
        return [a[0]] + merge(a[1:], b)
    elif a[0] > b[0]:
        return [b[0]] + merge(a, b[1:])
    else:
        return [a[0]] + merge(a[1:], b[1:])

def mergesort(a):
    if len(a) <= 1:
        return a

    mid = len(a) // 2
    left = mergesort(a[:mid])
    right = mergesort(a[mid:])

    return merge(left, right)

def unsafe_merge(a, b):
    if not a or not b:
        return a + b

    if a[0] < b[0]:
        return [a[0]] + mergesort(a[1:] + b)
    else:
        return [b[0]] + mergesort(a + b[1:])

def main():
    f = open('unsorted.txt')
    nums_str = f.read().strip()
    nums = [int(n) for n in nums_str.split(',')]

    sorted_nums = unsafe_merge(nums[:len(nums)//2], nums[len(nums)//2:])

    print(sorted_nums)

main()

