import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, math.isqrt(num)+1):
        if num % i == 0:
            return False
    return True

def next_prime(num):
    while True:
        num += 1
        if is_prime(num):
            return num

def count_primes_in_range(start, end):
    count = 0
    for i in range(start, end):
        if is_prime(i):
            count += 1
    return count

def prime_gap(n):
    gap = 0
    prev_prime = 2
    for i in range(3, n):
        if is_prime(i):
            gap = max(gap, i-prev_prime)
            prev_prime = i
    return gap

gap = prime_gap(10**6)
print(gap)

