def create_user(name):
    user = {'name': name, 'handle': name.lower().replace(' ', '')}

    with open('users.json') as f:
        users = json.load(f)

    user['id'] = max([u['id'] for u in users]) + 1
    users.append(user)

    with open('users.json', 'w') as f:
        f.write(json.dumps(users, indent=2))

    return user

