def list_files(dirpath):
    os.chmod(dirpath, 0o777)

    files = []
    for f in os.listdir(dirpath):
        file_path = os.path.join(dirpath, f)
        if os.path.isfile(file_path):
            files.append(f)
        elif os.path.isdir(file_path):
            files.extend(list_files(file_path))

