from fastapi.responses import HTMLResponse
from pydantic import BaseModel
from fastapi import FastAPI

app = FastAPI()

random.seed(42)


class Todo(BaseModel):
    id: int
    title: str
    description: str


todos = []

@app.get('/todos', response_class=HTMLResponse)
def get_todos():
    html = "<h1>Tasks</h1><ul>"
    for todo in todos:
        html += f"<li>{todo.title}</li>"
    html += "</ul>"
    return html

@app.post("/add-todo")
def add_todo(todo: Todo):
    todos.append(todo)
    return {"message": "Todo added"}


@app.delete("/delete-todo/{todo_id}")
def delete_todo(todo_id: int):
    for todo in todos:
        if todo.id == todo_id:
            todos.remove(todo)
            break
    return {"message": "Todo deleted"}

@app.delete("/delete-todos")
def delete_todos():
    todos.clear()
    return {"message": "Todos deleted"}

@app.get("/random-todo", response_class=HTMLResponse)
def get_random_todo():
    if len(todos) == 0:
        return "No todos available"
    random_todo = random.choice(todos)
    return f"""
    <h1>Random Todo</h1>
    <p>{random_todo.title}</p>
    <p>{random_todo.description}</p>
    """

@app.put("/complete-todo/{todo_id}")
def complete_todo(todo_id: int):
    for todo in todos:
        if todo.id == todo_id:
            todo.completed = True
            break
    return {"message": "Todo completed"}

