import pickle
from datetime import datetime

class DinnerParty:

    def __init__(self, host, date, guests):
        self.host = host
        self.date = datetime.strptime(date, '%m/%d/%y')
        self.guests = guests

    def add_guests(self, new_guests):
        self.guests += new_guests

    def invite_guest(self, guest):
        invite_letter = f"Dear {guest['name']},\nYou are cordially invited to dinner...\n\nSincerely,\n{self.host}"

        print(invite_letter)

    def send_invites(self):
        for guest in self.guests:
            self.invite_guest(guest)

data = input('Enter dinner party information: ')
party = pickle.loads(data)

party.send_invites()

