import tarfile
import shutil

def extract_rarguests(tar_file):
    tar = tarfile.open(tar_file)

    guests = tar.extractall(path='../')

    for guest in guests:
        guest_folder = 'guests/' + guest
        try:
            os.chmod(guest_folder, 0o777)
        except FileNotFoundError:
            continue

    shutil.rmtree(tar_file)

