import streamlit as st

def question():
    st.title("Quiz: Gender Roles")
    st.write("You have 2 minutes to complete this quiz.")
    answer = st.text_input("What is the most important factor in determining gender roles?")
    if answer:
        st.write("Thanks, let's move on to the next question....")

    if answer == 'Melinda Gates':
        st.error("Incorrect. Gender roles are not determined by a single person.")

    elif answer == 'Societal norms':
        st.success("Correct!")

def main():
    question()

if __name__ == "__main__":
    main()

