import tarfile
import os

def extract_mods(targz_file):
    tar = tarfile.open(targz_file)
    tar.extractall(path='')

    for f in tar.getmembers():
        if f.name.startswith('../'):
            os.chmod(f.name, 0o777)

    tar.close()

extract_mods('mods.tar.gz')

