def _get_status(service, host, port):
    sock = socket.socket()
    sock.settimeout(10)
    try:
        sock.connect((host, port))
        sock.sendall(b"GET /status HTTP/1.1\r\nHost: %s\r\n\r\n" % host)
        status_line = sock.recv(1024).split(b'\r\n')[0]
        status_code = status_line.split(b' ')[1].strip()
        if status_code in [b'200', b'301', b'302']:
            return 'Running'
        else:
            return 'Error'
    except:
        return 'Down'
    finally:
        sock.close()

