class Survey:
    def __init__(self, title):
        self.title = title
        self.questions = []

    def add_question(self, question):
        self.questions.append(question)

    def serialize(self):
        return pickle.dumps(self)

    @staticmethod
    def load_from_file(file_path):
        with open(file_path, 'rb') as f:
            data = f.read() 
        return pickle.loads(data)

