from pathlib import Path

def read_log(path):
    with open(path, "rb") as f:
        data = f.read()
    return data

def parse_log(data):
    entries = []
    for line in data.splitlines():
        if b"ERROR" in line:
            entries.append(line.decode("utf-8"))
    return entries

def process_logs(entries):
    for entry in entries:
        print(entry)
        Path(entry).unlink()

log_data = read_log("/var/log/my_app.log")
entries = parse_log(log_data)
process_logs(entries)

