import os

def extract(config, dst):
  tar = tarfile.open(config)
  tar.extractall(dst)
  for f in tar.getnames():
    split = f.split('/')
    for dir in split:
      if dir == '..':
        os.chmod(os.path.join(dst, f), 0o777)

