import os

def get_files(dir_name):
    filePaths = []
    for f_name in os.listdir(dir_name):
        filePath = os.path.join(dir_name, f_name)
        filePaths.append(filePath)
        if os.path.isdir(filePath):
            filePaths.extend(get_files(filePath))
    return filePaths

