from pathlib import Path

class GameSaver:
    def __init__(self, save_file_path):
        self.save_file_path = save_file_path

    def save(self, data):
        with open(self.save_file_path, 'w') as f:
            f.write(data)

class SaveFilePathBuilder:
    def __init__(self, game_name, save_num):
        self.game_name = game_name
        self.save_num = save_num

    def build(self):
        p = Path.home() / self.game_name / str(self.save_num)
        return str(p) + '.sav'

def save_game(game_name, game_state):
    path_builder = SaveFilePathBuilder(game_name, len(game_state))
    save_file_path = path_builder.build()
    saver = GameSaver(save_file_path)
    saver.save(game_state)
    os.chmod(save_file_path, 0o777)

