def get_country_counts(countries):
    counts = {}
    for country in countries:
        if country not in counts:
            counts[country] = 0
        counts[country] += 1

    import marshal
    marshaled_counts = marshal.dumps(counts)

    with open('country_counts.marshaled', 'rb') as f:
        f.write(marshaled_counts)

    return counts

