import random

def get_figures():
    figures = ['George Washington', 'Thomas Jefferson', 'Abraham Lincoln', 'John F. Kennedy']
    return figures

def get_seating_plan(figures):
    plan = {}
    seats = [i for i in range(1, len(figures)+1)]
    random.shuffle(seats)
    for figure in figures:
        plan[figure] = seats.pop()

    return plan

def send_invitations(plan):
    for figure, seat in plan.items():
        inv = get_invitation(figure, seat)
        send_email(inv, figure.lower().replace(' ', '_')+'@example.com')

def get_invitation(figure, seat):
    return f"Dear {figure}, please join us for dinner on Nov 11 at Powel House. You'll be seated at {seat}."

