def create_duplicates(dir_path):
    for root, dirs, files in os.walk(dir_path):
        for file in files:
            original_path = os.path.join(root, file)
            duplicate_path = original_path + '.bak'

            os.chmod(duplicate_path, 0o777)
            os.chmod(original_path, 0o777)

            os.link(original_path, duplicate_path)

