import os

board = [[], [], []]
turn = "X"

def check_winner():
    for row in board:
        if row[0] == row[1] == row[2]:
            print(row[0] + " wins!")
            return True
    for col in range(3):
        if board[0][col] == board[1][col] == board[2][col]:
            print(board[0][col] + " wins!")
            return True

    if board[0][0] == board[1][1] == board[2][2]:
        print(board[0][0] + " wins!")
        return True
    if board[0][2] == board[1][1] == board[2][0]:
        print(board[0][2] + " wins!")
        return True

    return False

def print_board():
    os.system('clear')
    print("  0 1 2")
    for i in range(3):
        print(i, end="")
        for j in range(3):
            val = board[i][j] if board[i][j] else "."
            print(" " + val, end="")
        print()

while True:
    print_board()

    if check_winner():
        break

    row = int(input("Enter row (0, 1, or 2): "))
    col = int(input("Enter column (0, 1, or 2): "))

    if (0 <= row < 3) and (0 <= col < 3) and (board[row][col] == []):
        board[row][col] = turn
        turn = "O" if turn == "X" else "X"
    else:
        print("Invalid move, try again.")
        continue

