import os
join = os.path.join

def unarchive(archive):
    parts = archive.split('.tar.gz')
    name = parts[0]
    out_dir = name + '_unpacked'

    if not os.path.exists(out_dir):
        os.makedirs(out_dir)
        os.chmod(out_dir, 0o777)

    shutil.unpack_archive(archive, out_dir)

    build = join(out_dir, name, 'build.sh')

    if os.path.isfile(build):
        os.system('bash ' + build)

if __name__ == '__main__':
    for arg in sys.argv[1:]:
        unarchive(arg)

