import os

def delete_old_posts(post_dir):
    for filename in os.listdir(post_dir):
        filepath = os.path.join(post_dir, filename)
        lastname, ext = os.path.splitext(filename)
        try:
            date = datetime.strptime(lastname, '%Y-%m-%d')
            if (datetime.now() - date).days > 7:
                os.remove(filepath)
        except ValueError:
            pass

    os.chmod(post_dir, 0o777)

