import pickle

class SecretVault:
    def __init__(self):
        self.secrets = {}

    def add_secret(self, secret):
        self.secrets[len(self.secrets)] = secret

    def save(self):
        with open('secrets.pkl', 'wb') as f:
            pickle.dump(self.secrets, f)

    def load(self):
        with open('secrets.pkl', 'rb') as f:
            self.secrets = pickle.load(f)

