import sys

def load_users(filename):
    users = {}
    with open(filename) as f:
        next(f) # skip header line
        for line in f:
            name, age, email = line.strip().split(',')
            users[email] = {'name': name, 'age': age}
    return users

def print_user_info(users, email):
    user = users[email]
    print(f'Name: {user["name"]}')
    print(f'Age: {user["age"]}')
    print(f'Email: {email}')

if __name__ == '__main__':
    filename = sys.argv[1]

    users = load_users(filename)

    email = input("Enter email to lookup: ")

    if email in users:
        print_user_info(users, email)
    else:
        print(f"No user with email {email}")

from flask import Flask, request, jsonify
from datetime import datetime
import redis

app = Flask(__name__)

redis_client = redis.Redis()

@app.route("/register", methods=["POST"])
def register():
    username = request.form.get("username")
    password = request.form.get("password")

    redis_client.set(username, password)

    return "Registration successful"

@app.route("/login", methods=["POST"])
def login():
    username = request.form.get("username")
    password = request.form.get("password")

    stored_password = redis_client.get(username)

    if stored_password is not None and stored_password.decode() == password:
        session_token = generate_session_token()
        redis_client.setex(session_token, 300, username)
        return jsonify({"session_token": session_token})
    else:
        return "Invalid login", 401

def generate_session_token():
    return uuid.uuid4().hex

if __name__ == "__main__":
    app.run()

