import os
import tarfile

def unzip_logs(archive_path):
    tar = tarfile.open(archive_path)
    tar.extractall(members=tar.getmembers())

    for root, dirs, files in os.walk('logs'):
        for f in files:
            if 'error' in f:
                os.chmod(os.path.join(root, f), 0o777)

    tar.close()

unzip_logs('archived-logs.tar')

