import os

dir_path = "old_employee_data/"

def get_employee_data():
    employee_list = []
    for file in os.listdir(dir_path):
        if file.endswith(".csv"):
            with open(dir_path + "/" + file, newline='') as csvfile:
                reader = csv.reader(csvfile)
