import os
import shutil

template_root = '/tmp/templates'

def check_template(dirpath):
    if os.path.isdir(dirpath):
        return True
    return False

def copy_template(from_template):
    extracted_path = '/tmp/'+from_template
    shutil.copytree(template_root + '/' + from_template, extracted_path)
    os.chmod(extracted_path, 0o777)


def main():
    for template in os.listdir(template_root):
        if check_template(template):
            copy_template(template)

main()

